现在所有上下文已经读全，可以给出完整的最小实现指导。以下是按推荐顺序的逐步代码片段与解释。

---

## 0. 新增头文件

在当前 `#include` 列表末尾加上：

```c
#include <zephyr/irq.h>
```

需要它是因为 `IRQ_CONNECT`、`irq_enable` 都来自这个头。`DT_INST_IRQN` / `DT_INST_IRQ` 等 devicetree 宏由 `device.h` 间接涵盖，不用再单独加。

---

## 1. 新增寄存器和比特位宏

在所有已有 `#define` 之后（第 6~13 行附近）、struct config 之前，追加：

```c
#define BK7258_UART_INT_ENABLE_OFFSET  0x20U
#define BK7258_UART_INT_FLAG_OFFSET    0x24U

#define BK7258_UART_INT_RX_NEED_READ   BIT(1)
#define BK7258_UART_INT_RX_STOP_END    BIT(6)

/* CPU0 中断使能门控寄存器（在系统控制器空间，不在 UART 内部） */
#define BK7258_UART_CPU0_INT_EN        0x44010080U
#define BK7258_UART1_CPU0_GATE         BIT(15)
```

**说明**：
- `INT_ENABLE`(0x20) 是 UART 模块内部的中断使能掩码。写 1 开启对应中断源，写 0 关闭。
- `INT_FLAG`(0x24) 显示当前哪些中断源 pending。**写 1 清除**对应位（write-1-to-clear）。
- `CPU0_INT_EN`(0x44010080) 是系统级别的 CPU0 中断门控，bit15 对应 UART1。这个寄存器不在 UART 地址空间，但必须在 init 时设置，否则 UART 中断根本到不了 NVIC。

---

## 2. data struct（"小本子"）

把第 68~71 行的占位注释替换为真正的 data struct：

```c
struct uart_bk7258_data {
    uart_irq_callback_user_data_t callback;
    void *callback_data;
    uint32_t irq_status;
};
```

位置：放在 config struct 之后、poll_out 函数之前。

**字段含义**：
- `callback` / `callback_data`：由 `irq_callback_set` 写入，ISR 调用。
- `irq_status`：ISR 入口处从 `INT_FLAG` 读到的原始值，缓存下来供 `irq_rx_ready` 查询。**这是核心设计**——因为 INT_FLAG 是 write-1-to-clear，ISR 必须立即读取并清除，否则 NVIC 会无限重入。清除之后 HW 就不再有状态了，所以必须把它存到 data 里。

---

## 3. fifo_read

放在 poll_in 函数之后：

```c
static int uart_bk7258_fifo_read(const struct device *dev, uint8_t *rx_data,
                                  const int size)
{
    const struct uart_bk7258_config *cfg = dev->config;
    int bytes_read = 0;

    while (bytes_read < size &&
           (sys_read32(cfg->base + BK7258_UART_FIFO_STATUS_OFFSET) &
            BK7258_UART_RX_READY_BIT)) {
        rx_data[bytes_read++] = (uint8_t)(
            (sys_read32(cfg->base + BK7258_UART_FIFO_PORT_OFFSET) >> 8) & 0xffU);
    }

    return bytes_read;
}
```

**为什么需要**：这是 Zephyr UART IRQ 模式下上层读取 RX 数据的标准入口。`irq_rx_ready` 说有数据，然后用 `fifo_read` 实际取出。

**和 poll_in 的区别**：`poll_in` 读一个字节就返回 0（成功），但 `fifo_read` 会尽量填满用户给的 buffer（最多 `size` 字节），返回实际读到的字节数。没有数据时返回 0（这不是错误，只是还没数据）。

---

## 4. fifo_fill（可选但推荐）

```c
static int uart_bk7258_fifo_fill(const struct device *dev, const uint8_t *tx_data,
                                  int len)
{
    const struct uart_bk7258_config *cfg = dev->config;
    int i;

    for (i = 0; i < len; i++) {
        if (sys_read32(cfg->base + BK7258_UART_FIFO_STATUS_OFFSET) &
            BK7258_UART_TX_FULL_BIT) {
            break;
        }
        sys_write32((uint32_t)tx_data[i] & 0xffU,
                    cfg->base + BK7258_UART_FIFO_PORT_OFFSET);
    }

    return i;
}
```

**注意**：你说不做 TX IRQ，但 `fifo_fill` 本身是同步写入（不依赖 IRQ），一些上层代码（如 `printk` 的某些实现）会调用它。提供它可以避免链接错误或退回到 poll_out。

---

## 5. 全部 irq_* 函数

所有以下函数放在 data struct 之后、`DEVICE_API` 之前。按逻辑分组解释：

### 5a. irq_callback_set —— 存回调指针

```c
static void uart_bk7258_irq_callback_set(const struct device *dev,
                                          uart_irq_callback_user_data_t cb,
                                          void *user_data)
{
    struct uart_bk7258_data *data = dev->data;

    data->callback = cb;
    data->callback_data = user_data;
}
```

### 5b. irq_update —— 无操作（状态已在 ISR 中缓存）

```c
static int uart_bk7258_irq_update(const struct device *dev)
{
    /* INT_FLAG 已在 uart_bk7258_isr() 入口处缓存到 data->irq_status，
     * 这里不再读 HW。返回 1 表示"状态已就绪"。
     */
    return 1;
}
```

### 5c. irq_rx_ready —— 检查 ISR 缓存的 INT_FLAG

```c
static int uart_bk7258_irq_rx_ready(const struct device *dev)
{
    struct uart_bk7258_data *data = dev->data;

    return (data->irq_status & BK7258_UART_INT_RX_NEED_READ) ? 1 : 0;
}
```

### 5d. irq_rx_enable / irq_rx_disable

```c
static void uart_bk7258_irq_rx_enable(const struct device *dev)
{
    const struct uart_bk7258_config *cfg = dev->config;
    uint32_t val;

    val = sys_read32(cfg->base + BK7258_UART_INT_ENABLE_OFFSET);
    val |= BK7258_UART_INT_RX_NEED_READ;
    sys_write32(val, cfg->base + BK7258_UART_INT_ENABLE_OFFSET);
}

static void uart_bk7258_irq_rx_disable(const struct device *dev)
{
    const struct uart_bk7258_config *cfg = dev->config;
    uint32_t val;

    val = sys_read32(cfg->base + BK7258_UART_INT_ENABLE_OFFSET);
    val &= ~BK7258_UART_INT_RX_NEED_READ;
    sys_write32(val, cfg->base + BK7258_UART_INT_ENABLE_OFFSET);
}
```

**风险点**：这里只用 bit1(RX_NEED_READ)，没有开 bit6(RX_STOP_END)。如果 bit6 触发了中断但 bit1 没触发，ISR 会调用 `irq_update` 然后 `irq_rx_ready` 返回 0，回调可能认为无事发生。如果能确认 bit6 在正常接收时不会单独触发，这样可以。如果 bit6 经常单独触发导致回调空转，可以考虑在 ISR 中也检查 bit6，或者在 `irq_rx_enable` 中也打开 bit6。

### 5e. TX 相关函数（stub，不做 TX IRQ）

```c
static void uart_bk7258_irq_tx_enable(const struct device *dev)
{
    /* TX IRQ not implemented */
}

static void uart_bk7258_irq_tx_disable(const struct device *dev)
{
}

static int uart_bk7258_irq_tx_ready(const struct device *dev)
{
    return 0;
}

static int uart_bk7258_irq_tx_complete(const struct device *dev)
{
    return 1;  /* 没有 TX IRQ，假设 tx 总是已完成 */
}
```

### 5f. 错误中断函数（stub）

```c
static void uart_bk7258_irq_err_enable(const struct device *dev)
{
}

static void uart_bk7258_irq_err_disable(const struct device *dev)
{
}
```

### 5g. irq_is_pending

```c
static int uart_bk7258_irq_is_pending(const struct device *dev)
{
    struct uart_bk7258_data *data = dev->data;

    return data->irq_status ? 1 : 0;
}
```

---

## 6. ISR 函数

在所有 irq_* 函数之后、init 函数之前加入：

```c
static void uart_bk7258_isr(const struct device *dev)
{
    struct uart_bk7258_data *data = dev->data;
    const struct uart_bk7258_config *cfg = dev->config;

    /* 第 1 步：读取 INT_FLAG 并清除（写 1 清除）。
     * 顺序很重要：必须先读后写。
     * 不清除会导致 NVIC 在 ISR 退出后立即重入 -> 死循环。
     */
    data->irq_status = sys_read32(cfg->base + BK7258_UART_INT_FLAG_OFFSET);
    sys_write32(data->irq_status, cfg->base + BK7258_UART_INT_FLAG_OFFSET);

    /* 第 2 步：分发给上层回调 */
    if (data->callback) {
        data->callback(dev, data->callback_data);
    }
}
```

### 关键提醒：为什么 ISR 不能 printf

ISR 里**绝对不能**调 `printk`/`printf`。`printk` 最终调用 `uart_bk7258_poll_out`，而 `poll_out` 做忙等（while TX_FULL），在 ISR 里忙等会：
- 阻塞整个系统，其他的 ISR 无法响应
- 如果 TX 中断和 RX 中断共享同一个优先级，会导致死锁
- 更危险的是如果 `printk` 依赖于某个 mutex（在 Zephyr 某些配置下），在 ISR 里获取 mutex 会导致 crash

验证方法：在回调函数里不要做 I/O，只把收到的数据塞进一个环形缓冲区，由线程上下文去打印。

---

## 7. 修改 init 函数

```c
static int uart_bk7258_init(const struct device *dev)
{
    const struct uart_bk7258_config *cfg = dev->config;
    uint32_t val;

    /* 1. 打开 UART RX（已有的） */
    val = sys_read32(cfg->base + BK7258_UART_CFG_OFFSET);
    val |= BK7258_UART_RX_ENABLE_BIT;
    sys_write32(val, cfg->base + BK7258_UART_CFG_OFFSET);

    /* 2. 打开 CPU0 的 UART1 中断门控（bit15）。
     *    使用读-改-写（而非直接写 BIT(15)），因为不确定
     *    这个寄存器是"直接写"还是"写1使能"语义。
     *    如果已知是 write-1-to-set，可简化为:
     *      sys_write32(BIT(15), BK7258_UART_CPU0_INT_EN);
     */
    val = sys_read32(BK7258_UART_CPU0_INT_EN);
    val |= BK7258_UART1_CPU0_GATE;
    sys_write32(val, BK7258_UART_CPU0_INT_EN);

    /* 3. 在 NVIC 中注册 ISR 并使能 UART1 IRQ(#15)
     *    IRQ_CONNECT 是"构建时注册"，放在函数体内是合法的——
     *    它生成一个放在 .gnu.linkonce 段的静态结构体。
     *    irq_enable 是真正的运行时调用，使能 NVIC 对应通道。
     */
    IRQ_CONNECT(DT_INST_IRQN(0), DT_INST_IRQ(0, priority),
                uart_bk7258_isr, DEVICE_DT_INST_GET(0), 0);
    irq_enable(DT_INST_IRQN(0));

    return 0;
}
```

### 风险点：CPU0 gate 写法

`SYS_CPU0_INT_0_31_EN`(0x44010080) 的语义可能是：
- **直接写寄存器**：整个寄存器 32 位就是要设置的值。用 `sys_write32(val, addr)`, 之前先 `sys_read32` 保持其他位不变。
- **write-1-to-set / write-0-to-clear**：只对对应位写 1 不会影响其他位。如果是这样，`sys_write32(BIT(15), addr)` 就够了。

上面给的读-改-写是最安全的。如果你确认它是 write-1-to-set，可以简化为 `sys_write32(BK7258_UART1_CPU0_GATE, BK7258_UART_CPU0_INT_EN)`。**建议先在 soc_reset_hook 或最小测试中验证这个寄存器的行为**。

---

## 8. 更新 DEVICE_API (driver_api) 结构体

把当前的：
```c
static DEVICE_API(uart, uart_bk7258_driver_api) = {
    .poll_in = uart_bk7258_poll_in,
    .poll_out = uart_bk7258_poll_out,
    .err_check = uart_bk7258_err_check,
};
```

改为：

```c
static DEVICE_API(uart, uart_bk7258_driver_api) = {
    .poll_in = uart_bk7258_poll_in,
    .poll_out = uart_bk7258_poll_out,
    .err_check = uart_bk7258_err_check,
#ifdef CONFIG_UART_INTERRUPT_DRIVEN
    .fifo_fill = uart_bk7258_fifo_fill,
    .fifo_read = uart_bk7258_fifo_read,
    .irq_tx_enable = uart_bk7258_irq_tx_enable,
    .irq_tx_disable = uart_bk7258_irq_tx_disable,
    .irq_tx_ready = uart_bk7258_irq_tx_ready,
    .irq_tx_complete = uart_bk7258_irq_tx_complete,
    .irq_rx_enable = uart_bk7258_irq_rx_enable,
    .irq_rx_disable = uart_bk7258_irq_rx_disable,
    .irq_rx_ready = uart_bk7258_irq_rx_ready,
    .irq_err_enable = uart_bk7258_irq_err_enable,
    .irq_err_disable = uart_bk7258_irq_err_disable,
    .irq_is_pending = uart_bk7258_irq_is_pending,
    .irq_update = uart_bk7258_irq_update,
    .irq_callback_set = uart_bk7258_irq_callback_set,
#endif
};
```

**重点**：`#ifdef CONFIG_UART_INTERRUPT_DRIVEN` 不能省。`uart_driver_api` 结构体本身的 IRQ 字段受这个 Kconfig 控制。如果你在未启用它时引用 `.fifo_read = ...`, 编译器会说这个 struct 没有 `fifo_read` 成员。

在应用的 `prj.conf`（或 `hello_world.conf`）中增加：
```
CONFIG_UART_INTERRUPT_DRIVEN=y
```

否则编译会报错："unknown field 'fifo_read' specified in initializer"。

